#include <Arduino.h>
#include <Adafruit_GFX.h>    
#include <Adafruit_ST7735.h> 
#include <SPI.h>

// ストラップピンを完全に避けた、安全なピン指定
#define TFT_RST    4   // 基板のD4 (GPIO 4)
#define TFT_DC     5   // 基板のD5 (GPIO 5)
#define TFT_CS     6   // 基板のD6 (GPIO 6)
#define TFT_MOSI   10  // 基板のD10
#define TFT_SCLK   8   // 基板のD8

Adafruit_ST7735 tft = Adafruit_ST7735(TFT_CS, TFT_DC, TFT_MOSI, TFT_SCLK, TFT_RST);

void setup() {
  // Chromebookの通知連打を防ぐ命綱
  Serial.begin(115200);
  delay(1000); 

  // 液晶の初期化
  tft.initR(INITR_BLACKTAB); 

  // 画面を「青色」で塗りつぶす
  tft.fillScreen(ST7735_BLUE);

  // 文字の設定
  tft.setCursor(10, 50);          
  tft.setTextColor(ST7735_WHITE); 
  tft.setTextSize(2);             

  // 文字を表示
  tft.println("Safe Boot!");
}

void loop() {
  // 画面が動いている間、裏で静かに認識を維持します
  Serial.println("LCD is running safely.");
  delay(2000);
}
